/** Injected by vite.config.js at build/dev-server start. */
declare const __BUILD_INFO__: {
  branch: string;
  commit: string;
  /** ISO date of the last commit, or null when git history is not available (then use builtAt). */
  commitDate: string | null;
  commitMessage: string;
  commitAuthor: string;
  builtAt: string;
};
